export const reverseEquityDefinitions={
  reverseCashBridge:{title:'Follow an upfront advance, accumulated interest and a separate property scenario',fields:[
    ['reverseHome','Starting home value in the hypothetical scenario (CAD)',750000,100000,3000000,25000],
    ['reverseAdvance','Gross initial loan advance before the entered fees (CAD)',200000,0,1000000,10000],
    ['reverseFees','Upfront costs deducted from that gross advance (CAD)',4000,0,20000,500],
    ['reverseOldDebt','Existing secured debt settled from the gross advance (CAD)',40000,0,500000,10000],
    ['reverseRate','Constant nominal annual loan rate in the model (%)',7,0,15,.25],
    ['reverseGrowth','Assumed annual home-value change (%)',2,-5,8,.5],
    ['reverseYears','Years until the hypothetical property sale',15,1,30,1],
    ['reverseSaleCosts','Assumed selling costs / modeled sale value (%)',4,0,10,.5]
  ]}
};
export function reverseEquityPath(input,years=input.reverseYears){
  const r=input.reverseRate/1200,rows=Array.from({length:years+1},(_,x)=>({x,debt:input.reverseAdvance*(1+r)**(x*12),home:input.reverseHome*(1+input.reverseGrowth/100)**x}));
  const end=rows.at(-1),selling=end.home*input.reverseSaleCosts/100,netProperty=end.home-selling;
  return {rows,end,netCash:input.reverseAdvance-input.reverseFees-input.reverseOldDebt,capitalizedInterest:end.debt-input.reverseAdvance,selling,netProperty,rawRemainder:netProperty-end.debt};
}
export function reverseEquityResult(kind,input){
  if(kind!=='reverseCashBridge')throw Error('Unknown retirement home-equity topic.');
  const p=reverseEquityPath(input);
  return {metrics:[['Advance less fees and old-debt settlement',p.netCash,'money'],['Modeled loan balance before contract protections',p.end.debt,'money'],['Sale remainder before contract protections',p.rawRemainder,'money']],note:'Hypothetical arithmetic, not a reverse-mortgage offer, approval, property appraisal or actual payout quote. One initial gross advance is borrowed; entered upfront costs and the listed old-debt payout are deducted from its proceeds and are not added to the new debt again. No further borrowing or regular repayments occur. The constant nominal annual rate is divided by 12 and interest capitalizes monthly; actual contract rates and compounding may differ. Home value changes at an independent assumed annual rate, and selling costs are a percentage of the modeled sale value. The debt balance is deliberately uncapped. A negative raw property remainder is an arithmetic gap before contractual protections, not a finding of personal or estate liability. No lender guarantee is calculated. Taxes, property upkeep, insurance, accrued post-due interest, other liens and the use of the cash advance are excluded.',charts:[
    {id:'reverse-equity-upfront-cash',type:'waterfall',title:'Reconcile the cash available from the initial advance',unit:'money',unitLabel:'CAD at the hypothetical starting date',rows:[{label:'Gross amount initially borrowed',value:input.reverseAdvance},{label:'Entered upfront costs deducted',value:-input.reverseFees},{label:'Existing secured debt settled',value:-input.reverseOldDebt}],totalLabel:'Net proceeds / cash needed',note:'Fees and the entered existing-debt payout are funded from the gross advance in this example. Debt starts at the gross amount, not the net proceeds. If the entered costs and old-debt payout exceed the advance, the negative endpoint is cash needed from another source. This does not verify fees, permitted borrowing or the net cash a lender would provide.'},
    {id:'reverse-equity-home-debt',type:'line',title:'Property value and the uncapped loan balance can grow at different rates',unit:'money',unitLabel:'CAD; separate hypothetical property and loan assumptions',xLabel:'Years after the initial advance',series:[{name:'Hypothetical home value before sale costs',rows:p.rows.map(r=>({x:r.x,value:r.home}))},{name:'Uncapped modeled debt',dash:true,rows:p.rows.map(r=>({x:r.x,value:r.debt}))}],note:'No interest is paid from household cash in the model, so accumulated interest is added to the balance. The home-value line is not an appraisal or an estimate of the cash retained after sale. Neither line incorporates eligibility rules, lender lending limits, default terms or a no-negative-equity guarantee.'},
    {id:'reverse-equity-interest-stack',type:'stackbar',title:'Separate the original advance from accumulated interest',unit:'money',unitLabel:'CAD; uncapped balances under independent elapsed-time scenarios',seriesNames:['Original gross advance','Capitalized interest'],rows:[5,10,15,20,30].map(years=>({label:years+' years',values:[input.reverseAdvance,reverseEquityPath(input,years).capitalizedInterest]})),note:'The original advance is unchanged. Interest compounds on the growing modeled balance at the same entered constant rate, with no regular payments or further advances. These balances are arithmetic scenarios, not valid future lender quotes or amounts guaranteed to be repayable under every contract.'},
    {id:'reverse-equity-sale-bridge',type:'waterfall',title:'Reconcile a hypothetical sale before applying any contract protections',unit:'money',unitLabel:'CAD at the selected sale year; raw arithmetic only',rows:[{label:'Modeled property sale value',value:p.end.home},{label:'Assumed selling costs',value:-p.selling},{label:'Uncapped modeled loan balance',value:-p.end.debt}],totalLabel:'Raw remainder / arithmetic gap',note:'The endpoint is modeled sale value less selling costs and the uncapped balance. It is not a lender payout calculation or a legal allocation of a loss. Conditional guarantees, contract obligations, repayment dates, other claims and actual sale evidence can change what is payable and retained.'},
    {id:'reverse-equity-rate-value-grid',type:'heatmap',title:'Stress the loan rate and home-value assumption separately',unit:'money',unitLabel:'Columns: annual home-value change. Rows: nominal loan rate. Cells: raw property remainder (CAD)',signed:true,columns:['−2%','0%','2%','4%'],rows:[4,6,8,10].map(reverseRate=>({label:reverseRate+'% loan',values:[-2,0,2,4].map(reverseGrowth=>reverseEquityPath({...input,reverseRate,reverseGrowth}).rawRemainder)})),note:'The selected gross advance, horizon and selling-cost percentage remain unchanged. Upfront costs and old-debt settlement affect initial net cash, not this property-only endpoint, because they were deducted from that advance at the start. Negative cells are uncapped arithmetic gaps before protections, not estimates of enforceable personal or estate debts. No probability or future rate offer is implied.'}
  ]};
}
